import{_ as a,o as i,c as e,a5 as o}from"./chunks/framework.BF53ZjCA.js";const f=JSON.parse('{"title":"鉴定工作流与记录","description":"","frontmatter":{"title":"鉴定工作流与记录","identification":"identification-workflow"},"headers":[],"relativePath":"zh/identification/identification-workflow.md","filePath":"zh/identification/identification-workflow.md","lastUpdated":1789155237000}'),r={name:"zh/identification/identification-workflow.md"};function n(l,t,d,h,s,p){return i(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="鉴定工作流与记录" tabindex="-1">鉴定工作流与记录 <a class="header-anchor" href="#鉴定工作流与记录" aria-label="Permalink to &quot;鉴定工作流与记录&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>专业鉴定不是寻找一个“神奇读数”，而是建立可复核的证据链。先记录样品状态， 再从低风险观察开始，逐步组合物理、光学和包裹体线索；最后明确结论的置信边界、 处理披露与是否需要实验室报告。</p><h2 id="鉴定步骤" tabindex="-1">鉴定步骤 <a class="header-anchor" href="#鉴定步骤" aria-label="Permalink to &quot;鉴定步骤&quot;">​</a></h2><p><strong>1. 先记录样品与任务边界</strong></p><p>记录尺寸、重量、镶嵌状态、已知来源、可见损伤和委托目的。镶嵌石、涂油石或无法接触 的样品，应在记录中注明哪些测试无法可靠完成。</p><p><strong>2. 从无损观察开始</strong></p><p>在白光、点光源和适当放大下观察体色、透明度、光泽、切工、包裹体与光学现象；先写下 观察事实，再写候选判断，避免把名称当成观察结果。</p><p><strong>3. 按风险递进测试</strong></p><p>优先考虑折射率、偏光镜、二色镜、紫外荧光和光谱等非破坏性线索；比重测试要评估样品 是否适合浸液，划痕测试只在必要且获准时考虑。</p><p><strong>4. 交叉验证与分级结论</strong></p><p>将读数与候选品种的特征范围、处理可能性和样品限制逐项比对。结论应区分“支持候选”、 “与候选一致”和“无法排除”，不要把单项测试写成最终鉴定。</p><p><strong>5. 需要时转交实验室</strong></p><p>涉及天然/合成判断、产地意见、重大交易或保险用途时，应保留原始记录并交由具备资质的 实验室完成更高阶检测。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>记录“看到了什么”与“因此怀疑什么”两栏，避免观察与结论互相污染。</li><li>仪器读数应带测试条件、方向、接触状态和重复结果，不能脱离上下文比较。</li><li>结论强度必须低于证据强度：筛分结果不是鉴定证书，产地意见也不是分级。</li><li>任何破坏性测试都要先确认授权、样品价值与安全条件。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>数值</th><th>备注</th></tr></thead><tbody><tr><td>镶嵌红宝石</td><td>先做筛分，并记录无法接触的测试</td><td>镶嵌状态限制</td></tr></tbody></table><p><em>详见<a href="./intro.html">鉴定总览</a>。</em></p>',19)])])}const _=a(r,[["render",n]]);export{f as __pageData,_ as default};
